fix_code:
public static void main(String[] args) {

    FastScanner sc = new FastScanner();
    PrintWriter out = new PrintWriter(System.out);

    int n = Integer.parseInt(sc.next());
    int m = Integer.parseInt(sc.next());
    long[] a = new long[n];
    for (int i = 0; i < n; i++) {
        a[i] = Long.parseLong(sc.next());
    }
    Arrays.sort(a);

    long[] b = new long[m];
    for (int i = 0; i < m; i++) {
        b[i] = Long.parseLong(sc.next());
    }
    Arrays.sort(b);

    int j = 0;
    long ans = 0L;
    for (int i = 0; i < m; i++) {
        if (j == n) { 
            out.println(-1); 
            out.flush(); 
            return; 
        }
        for (; j < n; j++) {
            if (a[j] >= b[i]) {
                ans += a[j];
                j++;
                break;
            }
            if (j == n - 1) {
                out.println(-1);
                out.flush();
                return;
            }
        }
    }
    out.println(ans);

    out.flush();
}
